'use strict';
// Date helpers for the reporting dashboard. All dates are treated as UTC.

const DAY = 86400000;

function startOfDay(date) {
  return Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate());
}

function daysBetween(a, b) {
  return Math.round((startOfDay(b) - startOfDay(a)) / DAY);
}

function addDays(date, n) {
  return new Date(startOfDay(date) + n * DAY);
}

// Thursday of the ISO week containing `date`; its year is the ISO week-year.
function isoThursday(date) {
  const dow = (date.getUTCDay() + 6) % 7; // Mon=0 .. Sun=6
  return new Date(startOfDay(date) + (3 - dow) * DAY);
}

// ISO-8601 week number.
function isoWeek(date) {
  const thu = isoThursday(date);
  const jan1 = Date.UTC(thu.getUTCFullYear(), 0, 1);
  return Math.floor((thu.getTime() - jan1) / DAY / 7) + 1;
}

// "2024-W11": the label the weekly report is filed under (ISO week-year).
function weekLabel(date) {
  return `${isoThursday(date).getUTCFullYear()}-W${String(isoWeek(date)).padStart(2, '0')}`;
}

module.exports = { daysBetween, addDays, isoWeek, weekLabel };
